INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','modal-obligation','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"modal-obligation","title":"Obligation, advice and prohibition","level":"B1","order":39,"summary":"Separate what is required, forbidden, unnecessary or advisable.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Must and have to","Forbidden is different from optional","Advice and expectations","Form questions and negatives correctly"],"rules":[{"title":"Must and have to","explanation":"Must and have to can both express obligation. Have to is especially useful for external requirements and for past or future forms. Must often expresses a strong rule or the speaker’s judgement. The distinction is a tendency, not a rigid division.","pattern":"You **must wear** a helmet. / We **had to wait**.","commonMistakes":["Must has no ordinary past-tense form for obligation. Use had to, not musted."],"examples":["The rule forbids the task. “You **must not** prepare the visitor guide.”","The rule forbids the task. “You **must not** restore the old portrait.”"],"skill":"form"},{"title":"Forbidden is different from optional","explanation":"**Must not** expresses prohibition. **Do not have to** means there is no obligation; the action is still allowed. This contrast is crucial when interpreting instructions. Need not can also mean that an action is unnecessary.","pattern":"You **must not enter**. / You **do not have to enter**.","commonMistakes":["Must not enter does not mean entering is optional. It means entering is forbidden."],"examples":["The task is optional and allowed. “You **do not have to** prepare the visitor guide.”","The task is optional and allowed. “You **do not have to** restore the old portrait.”"],"skill":"meaning"},{"title":"Advice and expectations","explanation":"Should and ought to commonly give advice or say what is expected. Should takes a bare infinitive; ought takes to. Had better gives stronger situation-specific advice and is followed by a base verb.","pattern":"You **should rest**. / You **ought to rest**. / You **had better rest**.","commonMistakes":["Had better is normally about the present or future despite had; it is not simply past advice."],"examples":["Give advice: “She should **prepare** the visitor guide before Friday.”","Give advice: “She should **restore** the old portrait before Friday.”"],"skill":"contrast"},{"title":"Form questions and negatives correctly","explanation":"Have to behaves like a lexical verb for do-support: Does she have to? She does not have to. Must and should form their own questions and negatives. Choose the auxiliary pattern that belongs to the expression.","pattern":"**Does she have to** leave? / **Should she** leave?","commonMistakes":["Does she has to? marks agreement twice; after does, use have."],"examples":["Ask about the requirement: “Does she **have to prepare** the visitor guide today?”","Ask about the requirement: “Does she **have to restore** the old portrait today?”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-obligation"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"f5f1c6d5-c018-5160-abc0-583a724bfebb","topicSlug":"modal-obligation","level":"B1","prompt":"The rule forbids the task. “You ____ prepare the visitor guide.”","choices":[{"id":"A","text":"must not"},{"id":"B","text":"do not have to"},{"id":"C","text":"may"},{"id":"D","text":"should"}],"answerId":"A","hint":"Decide whether the instruction means **forbidden** or merely **not required**.","explanation":"**Must not** means the action is forbidden, matching the explicit rule.","keywords":["prohibition"],"skill":"prohibition","contextKey":"modal-obligation-1","fingerprint":"73e9941df697b719b267e8f04133c2a42dff5c3d8cacc0adc36b705d4daae98d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-obligation"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Decide whether the instruction means **forbidden** or merely **not required**.","**Must not** means the action is forbidden, matching the explicit rule.","Choose **must not**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Must not** means the action is forbidden, matching the explicit rule.","B":"This means the task is optional, not forbidden.","C":"May would give permission or possibility.","D":"Should recommends the task, opposite to the prohibition."}}},{"id":"0e552d87-00f3-58c4-a17a-682df491c39a","topicSlug":"modal-obligation","level":"B1","prompt":"The task is optional and allowed. “You ____ prepare the visitor guide.”","choices":[{"id":"A","text":"must"},{"id":"B","text":"have to"},{"id":"C","text":"do not have to"},{"id":"D","text":"must not"}],"answerId":"C","hint":"Optional means **no obligation**, not prohibition.","explanation":"**Do not have to** means there is no obligation; the task remains allowed.","keywords":["no-obligation"],"skill":"no-obligation","contextKey":"modal-obligation-1","fingerprint":"b452e18e576b6c4f33471a553ac3a09938c7f0df5839c6722c2209b5cbd0c3bf","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-obligation"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Optional means **no obligation**, not prohibition.","**Do not have to** means there is no obligation; the task remains allowed.","Choose **do not have to**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Must would make it compulsory.","B":"Have to also makes it compulsory.","C":"**Do not have to** means there is no obligation; the task remains allowed.","D":"Must not would forbid it, contradicting allowed."}}},{"id":"2b491550-60cc-57ee-a848-0002a7e08606","topicSlug":"modal-obligation","level":"B1","prompt":"Give advice: “She should ____ the visitor guide before Friday.”","choices":[{"id":"A","text":"prepare"},{"id":"B","text":"prepares"},{"id":"C","text":"preparing"},{"id":"D","text":"to prepare"}],"answerId":"A","hint":"The modal **should** carries the advice; the following verb stays in base form.","explanation":"After **should**, use base **prepare**.","keywords":["advice-form"],"skill":"advice-form","contextKey":"modal-obligation-1","fingerprint":"de7056a677167cda3dbfe1bf21ea8918bd52bb3b87668f7e822c4fe6a90bdc48","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-obligation"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The modal **should** carries the advice; the following verb stays in base form.","After **should**, use base **prepare**.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After **should**, use base **prepare**.","B":"Should takes a base form without -s.","C":"Should alone cannot take the -ing form.","D":"Should takes a bare infinitive; ought is the expression that uses to."}}},{"id":"baf332a4-eb82-550c-ae79-5894ce81a183","topicSlug":"modal-obligation","level":"B1","prompt":"Ask about the requirement: “Does she ____ the visitor guide today?”","choices":[{"id":"A","text":"have prepare"},{"id":"B","text":"have to prepare"},{"id":"C","text":"has to prepare"},{"id":"D","text":"must prepare"}],"answerId":"B","hint":"Does is already present; choose **have to**, not has to.","explanation":"**Does** carries agreement, so use **have to prepare**.","keywords":["obligation-question"],"skill":"obligation-question","contextKey":"modal-obligation-1","fingerprint":"7acab055673ba039595ea8ab17796b56988b40d651cd479228ee93b1787c6a5f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-obligation"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Does is already present; choose **have to**, not has to.","**Does** carries agreement, so use **have to prepare**.","Choose **have to prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The obligation expression have to requires to.","B":"**Does** carries agreement, so use **have to prepare**.","C":"After does, use base have rather than has.","D":"Must forms its own question without does."}}},{"id":"da650be2-76d4-5992-a8a4-445b84154273","topicSlug":"modal-obligation","level":"B1","prompt":"The rule forbids the task. “You ____ restore the old portrait.”","choices":[{"id":"A","text":"must not"},{"id":"B","text":"do not have to"},{"id":"C","text":"may"},{"id":"D","text":"should"}],"answerId":"A","hint":"Decide whether the instruction means **forbidden** or merely **not required**.","explanation":"**Must not** means the action is forbidden, matching the explicit rule.","keywords":["prohibition"],"skill":"prohibition","contextKey":"modal-obligation-2","fingerprint":"a1a6154b6d197c9dcc687d37f425b5461f56b45b99671548f81c4726b8ecf9d7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-obligation"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Decide whether the instruction means **forbidden** or merely **not required**.","**Must not** means the action is forbidden, matching the explicit rule.","Choose **must not**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Must not** means the action is forbidden, matching the explicit rule.","B":"This means the task is optional, not forbidden.","C":"May would give permission or possibility.","D":"Should recommends the task, opposite to the prohibition."}}},{"id":"c40e8a8b-bf5a-58d6-a679-dd2cf91a4819","topicSlug":"modal-obligation","level":"B1","prompt":"The task is optional and allowed. “You ____ restore the old portrait.”","choices":[{"id":"A","text":"do not have to"},{"id":"B","text":"must not"},{"id":"C","text":"must"},{"id":"D","text":"have to"}],"answerId":"A","hint":"Optional means **no obligation**, not prohibition.","explanation":"**Do not have to** means there is no obligation; the task remains allowed.","keywords":["no-obligation"],"skill":"no-obligation","contextKey":"modal-obligation-2","fingerprint":"da053c788ae0060fc22c5835ebd3bb7ef4039259867ab0620f2dc3117eb38e48","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-obligation"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Optional means **no obligation**, not prohibition.","**Do not have to** means there is no obligation; the task remains allowed.","Choose **do not have to**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Do not have to** means there is no obligation; the task remains allowed.","B":"Must not would forbid it, contradicting allowed.","C":"Must would make it compulsory.","D":"Have to also makes it compulsory."}}},{"id":"1f49cb0e-d30c-59ac-a7a5-79f46fdcdbb7","topicSlug":"modal-obligation","level":"B1","prompt":"Give advice: “She should ____ the old portrait before Friday.”","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"restore"},{"id":"C","text":"restores"},{"id":"D","text":"restoring"}],"answerId":"B","hint":"The modal **should** carries the advice; the following verb stays in base form.","explanation":"After **should**, use base **restore**.","keywords":["advice-form"],"skill":"advice-form","contextKey":"modal-obligation-2","fingerprint":"c87c48ad7